    static let fileManagerHTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<title>文件管理</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n\n/* 深空极光主题变量（云端可覆盖，默认 aurora） */\n:root {\n    --primary: #7C4DFF;\n    --accent: #00E5FF;\n    --bg-a: #0a0a1e;\n    --bg-b: #1f1233;\n    --bg-c: #0a1a33;\n    --card: rgba(255,255,255,0.08);\n    --card-strong: rgba(255,255,255,0.12);\n    --text: #e6e6f0;\n    --text-dim: #9aa0b5;\n    --danger: #ef5350;\n    --radius: 14px;\n    --font-scale: 1;\n}\n\nbody {\n    font-family: -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Helvetica Neue', sans-serif;\n    background: linear-gradient(135deg, var(--bg-a) 0%, var(--bg-b) 45%, var(--bg-c) 100%);\n    background-attachment: fixed;\n    min-height: 100vh;\n    color: var(--text);\n    font-size: calc(14px * var(--font-scale));\n    user-select: none;\n}\n\n.header {\n    background: var(--card);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    padding: 12px 16px;\n    position: sticky; top: 0; z-index: 100;\n    box-shadow: 0 1px 0 rgba(255,255,255,0.06);\n}\n.header-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }\n.header h1 { font-size: 18px; font-weight: 700; color: var(--primary); }\n.path-bar {\n    display: flex; align-items: center; gap: 6px;\n    background: var(--card-strong); border-radius: 10px; padding: 8px 12px;\n    font-size: 13px; overflow-x: auto; white-space: nowrap;\n}\n.path-bar span { color: var(--text-dim); cursor: pointer; }\n.path-bar span:hover { color: var(--accent); }\n.path-bar .sep { color: var(--text-dim); opacity: 0.5; }\n.actions { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }\n.btn {\n    padding: 8px 14px; border-radius: 10px; border: none;\n    font-size: 13px; font-weight: 600; cursor: pointer;\n    display: inline-flex; align-items: center; gap: 4px;\n    transition: transform 0.1s, opacity 0.1s;\n}\n.btn:active { transform: scale(0.96); opacity: 0.8; }\n.btn-primary { background: var(--primary); color: white; }\n.btn-secondary { background: var(--accent); color: #04222a; }\n.btn-success { background: #5cc873; color: white; }\n.btn-danger { background: var(--danger); color: white; }\n.btn-gray { background: var(--card-strong); color: var(--text); }\n.file-list { padding: 12px 16px; }\n.file-item {\n    display: flex; align-items: center; gap: 12px;\n    padding: 12px; background: var(--card);\n    border-radius: 12px; margin-bottom: 8px;\n    transition: background 0.15s;\n}\n.file-item:active { background: var(--card-strong); }\n.file-icon { font-size: 28px; width: 36px; text-align: center; }\n.file-info { flex: 1; min-width: 0; }\n.file-name { font-size: 15px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.file-meta { font-size: 11px; color: var(--text-dim); margin-top: 2px; }\n.file-actions { display: flex; gap: 6px; opacity: 0; transition: opacity 0.2s; }\n.file-item.selected .file-actions { opacity: 1; }\n.mini-btn {\n    padding: 6px 10px; border-radius: 8px; border: none;\n    font-size: 11px; font-weight: 600; cursor: pointer;\n}\n.mini-btn.copy { background: rgba(0,229,255,0.15); color: var(--accent); }\n.mini-btn.danger { background: rgba(239,83,80,0.15); color: #ff8a80; }\n.empty { text-align: center; padding: 60px 20px; color: var(--text-dim); }\n.empty-icon { font-size: 48px; margin-bottom: 12px; }\n\n/* 下载面板 */\n.download-panel {\n    margin: 12px 16px; padding: 14px;\n    background: var(--card); border-radius: var(--radius);\n}\n.download-panel h3 { font-size: 14px; margin-bottom: 10px; color: var(--primary); }\n.download-row { display: flex; gap: 8px; margin-bottom: 8px; }\n.download-row input {\n    flex: 1; padding: 10px 12px; border: 1px solid var(--card-strong);\n    border-radius: 10px; font-size: 13px; outline: none;\n    background: var(--card); color: var(--text);\n}\n.download-row input:focus { border-color: var(--accent); }\n.shortcut-list { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }\n.shortcut-tag {\n    padding: 6px 12px; background: rgba(124,77,255,0.15); border-radius: 20px;\n    font-size: 12px; color: var(--primary); cursor: pointer;\n    border: 1px solid rgba(124,77,255,0.35);\n}\n.shortcut-tag:active { background: rgba(124,77,255,0.3); }\n\n/* Toast */\n.toast {\n    position: fixed; bottom: 80px; left: 50%; transform: translateX(-50%);\n    background: rgba(0,0,0,0.8); color: white; padding: 10px 20px;\n    border-radius: 20px; font-size: 13px; z-index: 999;\n    opacity: 0; transition: opacity 0.3s; pointer-events: none;\n}\n.toast.show { opacity: 1; }\n\n/* 加载 */\n.loading { text-align: center; padding: 40px; color: var(--text-dim); }\n.spinner {\n    display: inline-block; width: 24px; height: 24px;\n    border: 3px solid var(--card-strong); border-top-color: var(--accent);\n    border-radius: 50%; animation: spin 0.8s linear infinite;\n}\n@keyframes spin { to { transform: rotate(360deg); } }\n\n/* 上下文菜单 */\n.context-menu {\n    position: fixed; background: #16162a; border-radius: 12px;\n    box-shadow: 0 4px 20px rgba(0,0,0,0.5); padding: 6px; z-index: 200;\n    min-width: 140px; color: var(--text);\n    border: 1px solid var(--card-strong);\n}\n.context-menu button {\n    display: block; width: 100%; text-align: left;\n    padding: 10px 14px; border: none; background: none;\n    font-size: 14px; cursor: pointer; border-radius: 8px; color: var(--text);\n}\n.context-menu button:active { background: var(--card-strong); color: var(--accent); }\n</style>\n</head>\n<body>\n\n<div class=\"header\">\n    <div class=\"header-top\">\n        <h1>📁 文件管理</h1>\n        <div style=\"display:flex;gap:6px;\">\n            <button class=\"btn btn-gray\" onclick=\"goHome()\">🏠</button>\n            <button class=\"btn btn-gray\" onclick=\"goUp()\">⬆️</button>\n        </div>\n    </div>\n    <div class=\"path-bar\" id=\"pathBar\"></div>\n    <div class=\"actions\">\n        <button class=\"btn btn-primary\" onclick=\"showDownloadPanel()\">⬇️ 下载直链</button>\n        <button class=\"btn btn-secondary\" onclick=\"newFolder()\">📁 新建</button>\n        <button class=\"btn btn-success\" onclick=\"pasteFromClipboard()\">📋 粘贴</button>\n    </div>\n</div>\n\n<!-- 一键下载面板 -->\n<div class=\"download-panel\" id=\"downloadPanel\" style=\"display:none;\">\n    <h3>⬇️ 一键下载直链并导入</h3>\n    <div class=\"download-row\">\n        <input type=\"text\" id=\"urlInput\" placeholder=\"粘贴直链 URL (https://...)\" />\n        <button class=\"btn btn-primary\" onclick=\"downloadURL()\">下载</button>\n    </div>\n    <div class=\"download-row\">\n        <input type=\"text\" id=\"filenameInput\" placeholder=\"文件名（可选，留空用远程文件名）\" />\n    </div>\n    <div class=\"shortcut-list\" id=\"shortcutList\"></div>\n</div>\n\n<div class=\"file-list\" id=\"fileList\">\n    <div class=\"loading\"><div class=\"spinner\"></div><p style=\"margin-top:10px;\">加载中...</p></div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n<div class=\"context-menu\" id=\"contextMenu\" style=\"display:none;\"></div>\n\n<script>\n// ============ JS Bridge ============\nlet callbackCounter = 0;\nconst callbacks = {};\n\nfunction callNative(action, params) {\n    return new Promise((resolve, reject) => {\n        const callbackId = 'cb_' + (++callbackCounter);\n        callbacks[callbackId] = { resolve, reject };\n        const message = Object.assign({ action, callbackId }, params || {});\n        window.webkit.messageHandlers.fileBridge.postMessage(message);\n    });\n}\n\nwindow.__bridgeCallback = function(response) {\n    const cb = callbacks[response.callbackId];\n    if (!cb) return;\n    delete callbacks[response.callbackId];\n    if (response.error) {\n        cb.reject(response.error);\n    } else {\n        cb.resolve(response.data);\n    }\n};\n\n// ============ 主题 ============\nfunction applyTheme() {\n    const t = window.__theme || {};\n    const root = document.documentElement;\n    const set = (k, v) => { if (v !== undefined && v !== null && v !== '') root.style.setProperty(k, v); };\n    set('--primary', t.primary);\n    set('--accent', t.accent);\n    set('--radius', t.cornerRadius ? (t.cornerRadius + 'px') : undefined);\n    set('--font-scale', t.fontScale || 1);\n    const bg = t.background || 'aurora';\n    if (bg === 'light') {\n        set('--bg-a', '#ffeef4'); set('--bg-b', '#eef2ff'); set('--bg-c', '#eef2ff');\n        set('--card', 'rgba(255,255,255,0.9)'); set('--card-strong', 'rgba(0,0,0,0.05)');\n        set('--text', '#1a1a1a'); set('--text-dim', '#888');\n    } else if (bg === 'dark') {\n        set('--bg-a', '#05050a'); set('--bg-b', '#05050a'); set('--bg-c', '#05050a');\n        set('--card', 'rgba(255,255,255,0.08)'); set('--card-strong', 'rgba(255,255,255,0.14)');\n        set('--text', '#e6e6f0'); set('--text-dim', '#9aa0b5');\n    }\n}\n\n// ============ 状态 ============\nlet currentPath = '';\nlet clipboard = null;\nlet selectedFile = null;\nlet appInfo = null;\nlet shortcuts = [];\n\n// ============ 初始化 ============\nasync function init() {\n    applyTheme();\n    try {\n        appInfo = await callNative('appInfo');\n        currentPath = appInfo.startPath || appInfo.documentsDir;\n        loadShortcuts();\n        await refresh();\n    } catch (e) {\n        showToast('初始化失败: ' + e);\n    }\n}\n\nfunction loadShortcuts() {\n    if (window.__shortcuts) {\n        shortcuts = window.__shortcuts;\n        renderShortcuts();\n    }\n}\n\nfunction renderShortcuts() {\n    const list = document.getElementById('shortcutList');\n    if (!shortcuts.length) { list.innerHTML = ''; return; }\n    list.innerHTML = shortcuts.map(s =>\n        `<span class=\"shortcut-tag\" onclick=\"quickDownload('${s.url}','${s.targetDir}','${s.name}')\">⚡ ${s.name}</span>`\n    ).join('');\n}\n\n// ============ 路径渲染 ============\nfunction renderPathBar() {\n    const bar = document.getElementById('pathBar');\n    const parts = currentPath.split('/').filter(Boolean);\n    let html = `<span onclick=\"goToPath('/')\">/</span>`;\n    let accumulated = '';\n    parts.forEach((part, i) => {\n        accumulated += '/' + part;\n        html += `<span class=\"sep\">/</span><span onclick=\"goToPath('${accumulated}')\">${part}</span>`;\n    });\n    bar.innerHTML = html;\n}\n\n// ============ 文件列表 ============\nasync function refresh() {\n    renderPathBar();\n    const list = document.getElementById('fileList');\n    list.innerHTML = '<div class=\"loading\"><div class=\"spinner\"></div><p style=\"margin-top:10px;\">加载中...</p></div>';\n\n    try {\n        const data = await callNative('list', { path: currentPath });\n        const items = (data.items || []).sort((a, b) => {\n            if (a.isDirectory !== b.isDirectory) return a.isDirectory ? -1 : 1;\n            return a.name.localeCompare(b.name);\n        });\n\n        if (items.length === 0) {\n            list.innerHTML = '<div class=\"empty\"><div class=\"empty-icon\">📂</div><p>此目录为空</p></div>';\n            return;\n        }\n\n        list.innerHTML = items.map(item => {\n            const icon = item.isDirectory ? '📁' : getFileIcon(item.name);\n            const size = item.isDirectory ? '' : formatSize(item.size);\n            const date = item.modificationDate ? new Date(item.modificationDate * 1000).toLocaleString('zh-CN') : '';\n            return `\n                <div class=\"file-item\" data-path=\"${item.path}\" data-dir=\"${item.isDirectory}\">\n                    <div class=\"file-icon\">${icon}</div>\n                    <div class=\"file-info\">\n                        <div class=\"file-name\">${item.name}</div>\n                        <div class=\"file-meta\">${size} ${date}</div>\n                    </div>\n                    <div class=\"file-actions\">\n                        <button class=\"mini-btn copy\" onclick=\"event.stopPropagation();copyItem('${item.path}')\">复制</button>\n                        <button class=\"mini-btn danger\" onclick=\"event.stopPropagation();deleteItem('${item.path}')\">删除</button>\n                    </div>\n                </div>\n            `;\n        }).join('');\n\n        list.querySelectorAll('.file-item').forEach(el => {\n            el.addEventListener('click', () => {\n                const path = el.dataset.path;\n                const isDir = el.dataset.dir === 'true';\n                if (isDir) {\n                    goToPath(path);\n                } else {\n                    showContextMenu(path);\n                }\n            });\n        });\n    } catch (e) {\n        list.innerHTML = `<div class=\"empty\"><div class=\"empty-icon\">⚠️</div><p>加载失败: ${e}</p></div>`;\n    }\n}\n\nfunction getFileIcon(name) {\n    const ext = name.split('.').pop().toLowerCase();\n    const icons = {\n        png:'🖼️', jpg:'🖼️', jpeg:'🖼️', gif:'🖼️', webp:'🖼️', heic:'🖼️',\n        mp4:'🎬', mov:'🎬', avi:'🎬', mkv:'🎬',\n        mp3:'🎵', wav:'🎵', flac:'🎵', aac:'🎵',\n        zip:'🗜️', rar:'🗜️', '7z':'🗜️', tar:'🗜️', gz:'🗜️',\n        txt:'📄', md:'📄', json:'📄', xml:'📄', plist:'📄',\n        pdf:'📕', doc:'📘', docx:'📘', xls:'📗', xlsx:'📗',\n        js:'📜', html:'🌐', css:'🎨', swift:'🐦', py:'🐍',\n        deb:'📦', ipa:'📱', dylib:'🔧', framework:'🔧'\n    };\n    return icons[ext] || '📄';\n}\n\nfunction formatSize(bytes) {\n    if (bytes === 0) return '0 B';\n    const units = ['B','KB','MB','GB','TB'];\n    const i = Math.floor(Math.log(bytes) / Math.log(1024));\n    return (bytes / Math.pow(1024, i)).toFixed(1) + ' ' + units[i];\n}\n\n// ============ 导航 ============\nfunction goToPath(path) {\n    currentPath = path;\n    hideContextMenu();\n    refresh();\n}\n\nfunction goHome() {\n    if (appInfo) goToPath(appInfo.documentsDir || appInfo.homeDir);\n}\n\nfunction goUp() {\n    const parts = currentPath.split('/');\n    parts.pop();\n    goToPath(parts.join('/') || '/');\n}\n\n// ============ 文件操作 ============\nasync function copyItem(path) {\n    clipboard = { type: 'copy', path };\n    showToast('已复制，点击「粘贴」到目标目录');\n}\n\nasync function cutItem(path) {\n    clipboard = { type: 'move', path };\n    showToast('已剪切，点击「粘贴」到目标目录');\n}\n\nasync function pasteFromClipboard() {\n    if (!clipboard) { showToast('剪贴板为空'); return; }\n    try {\n        const name = clipboard.path.split('/').pop();\n        const dest = (currentPath + '/' + name).replace(/\\/+/g, '/');\n        if (clipboard.type === 'copy') {\n            await callNative('copy', { src: clipboard.path, dst: dest });\n            showToast('复制成功');\n        } else {\n            await callNative('move', { src: clipboard.path, dst: dest });\n            showToast('移动成功');\n            clipboard = null;\n        }\n        refresh();\n    } catch (e) { showToast('操作失败: ' + e); }\n}\n\nasync function deleteItem(path) {\n    if (!confirm('确定删除？')) return;\n    try {\n        await callNative('delete', { path });\n        showToast('已删除');\n        refresh();\n    } catch (e) { showToast('删除失败: ' + e); }\n}\n\nasync function newFolder() {\n    const name = prompt('文件夹名称');\n    if (!name) return;\n    try {\n        const path = (currentPath + '/' + name).replace(/\\/+/g, '/');\n        await callNative('mkdir', { path });\n        showToast('已创建');\n        refresh();\n    } catch (e) { showToast('创建失败: ' + e); }\n}\n\n// ============ 下载功能 ============\nfunction showDownloadPanel() {\n    const panel = document.getElementById('downloadPanel');\n    panel.style.display = panel.style.display === 'none' ? 'block' : 'none';\n}\n\nasync function downloadURL() {\n    const url = document.getElementById('urlInput').value.trim();\n    const filename = document.getElementById('filenameInput').value.trim();\n    if (!url) { showToast('请输入直链'); return; }\n\n    showToast('开始下载...');\n    try {\n        const result = await callNative('download', {\n            url: url,\n            targetDir: currentPath,\n            filename: filename || '',\n            autoImport: true\n        });\n        showToast(`下载成功: ${formatSize(result.size)} -> ${result.path.split('/').pop()}`);\n        document.getElementById('urlInput').value = '';\n        document.getElementById('filenameInput').value = '';\n        refresh();\n    } catch (e) { showToast('下载失败: ' + e); }\n}\n\nasync function quickDownload(url, targetDir, name) {\n    showToast(`开始下载 ${name}...`);\n    try {\n        const result = await callNative('download', {\n            url: url,\n            targetDir: targetDir,\n            filename: name,\n            autoImport: true\n        });\n        showToast(`导入成功: ${name}`);\n        refresh();\n    } catch (e) { showToast('下载失败: ' + e); }\n}\n\n// ============ 上下文菜单 ============\nfunction showContextMenu(path) {\n    const menu = document.getElementById('contextMenu');\n    selectedFile = path;\n    menu.innerHTML = `\n        <button onclick=\"copyItem('${path}');hideContextMenu()\">📋 复制</button>\n        <button onclick=\"cutItem('${path}');hideContextMenu()\">✂️ 剪切</button>\n        <button onclick=\"renameItem('${path}')\">✏️ 重命名</button>\n        <button onclick=\"deleteItem('${path}');hideContextMenu()\">🗑️ 删除</button>\n        <button onclick=\"shareItem('${path}')\">📤 分享</button>\n        <button onclick=\"hideContextMenu()\">取消</button>\n    `;\n    menu.style.display = 'block';\n    menu.style.left = '50%';\n    menu.style.top = '50%';\n    menu.style.transform = 'translate(-50%, -50%)';\n}\n\nfunction hideContextMenu() {\n    document.getElementById('contextMenu').style.display = 'none';\n}\n\nasync function renameItem(path) {\n    const oldName = path.split('/').pop();\n    const newName = prompt('新名称', oldName);\n    if (!newName || newName === oldName) { hideContextMenu(); return; }\n    try {\n        const newPath = path.substring(0, path.length - oldName.length) + newName;\n        await callNative('move', { src: path, dst: newPath });\n        showToast('已重命名');\n        refresh();\n    } catch (e) { showToast('重命名失败: ' + e); }\n    hideContextMenu();\n}\n\nfunction shareItem(path) {\n    showToast('分享功能调用原生');\n    hideContextMenu();\n}\n\n// ============ Toast ============\nfunction showToast(msg) {\n    const toast = document.getElementById('toast');\n    toast.textContent = msg;\n    toast.classList.add('show');\n    clearTimeout(window._toastTimer);\n    window._toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);\n}\n\ndocument.addEventListener('click', (e) => {\n    const menu = document.getElementById('contextMenu');\n    if (menu.style.display === 'block' && !menu.contains(e.target)) {\n        hideContextMenu();\n    }\n});\n\ninit();\n</script>\n</body>\n</html>"
